= Route116_EventScript_BrineyTrigger
lockall
applymovement LOCALID_ROUTE116_BRINEY Common_Movement_WalkInPlaceFasterRight
applymovement LOCALID_PLAYER Common_Movement_WalkInPlaceFasterLeft
waitmovement 0
msgbox	Ohhh, what am I to do?We were on our walk, PEEKO and I, when we were jumped by an odd thug…The scoundrel made off with my darling PEEKO!Wrrrooooooaaaar! PEEKO!
setvar VAR_ROUTE116_STATE 2
releaseall
end
= Route116_EventScript_Devan
trainerbattle_single TRAINER_DEVAN Route116_Text_DevanIntro Route116_Text_DevanDefeat
msgbox	I should try different POKéMON types, that's what I ought to do.
end
= Route116_EventScript_Johnson
trainerbattle_single TRAINER_JOHNSON Route116_Text_JohnsonIntro Route116_Text_JohnsonDefeat
msgbox	Want to stay here and keep me company?
end
= EventScript_CutTree
lockall
goto_if_unset FLAG_BADGE01_GET EventScript_CheckTreeCantCut
checkpartymove MOVE_CUT
goto_if_eq VAR_RESULT PARTY_SIZE EventScript_CheckTreeCantCut
setfieldeffectargument 0 VAR_RESULT
bufferpartymonnick STR_VAR_1 VAR_RESULT
buffermovename STR_VAR_2 MOVE_CUT
msgboxyesno	This tree looks like it can be CUT down!Would you like to CUT it?
goto_if_eq VAR_RESULT NO EventScript_CancelCut
msgbox	STR_VAR_1 used STR_VAR_2!
closemessage
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
@ Use cut from party menu
goto EventScript_UseCut
= EventScript_UseCut
lockall
dofieldeffect FLDEFF_USE_CUT_ON_TREE
waitstate
goto EventScript_CutTreeDown
end
= EventScript_CutTreeDown
applymovement VAR_LAST_TALKED Movement_CutTreeDown
waitmovement 0
removeobject VAR_LAST_TALKED
releaseall
end
= EventScript_CancelCut
closemessage
releaseall
end
= EventScript_CheckTreeCantCut
msgbox	This tree looks like it can be CUT down!
releaseall
end
